from collections import deque

def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    # Aho-Corasick Automaton construction
    # Each node is represented as an index
    # trie structure: children list of dicts, fail link list, is_banned flag list
    children = [{}]
    fail = [0]
    is_banned = [False]

    for word in banned:
        curr = 0
        for char in word:
            if char not in children[curr]:
                children[curr][char] = len(children)
                children.append({})
                fail.append(0)
                is_banned.append(False)
            curr = children[curr][char]
        is_banned[curr] = True

    queue = deque()
    for char, nxt in children[0].items():
        queue.append(nxt)

    while queue:
        u = queue.popleft()
        if is_banned[fail[u]]:
            is_banned[u] = True
        for char, v in children[u].items():
            f = fail[u]
            while f > 0 and char not in children[f]:
                f = fail[f]
            if char in children[f]:
                fail[v] = children[f][char]
            else:
                fail[v] = 0
            queue.append(v)

    # Filter out banned nodes
    valid_nodes = [i for i in range(len(children)) if not is_banned[i]]
    if 0 not in valid_nodes:
        return 0
    node_to_idx = {node: i for i, node in enumerate(valid_nodes)}
    m = len(valid_nodes)

    # Precompute transition function delta(u, char)
    def get_next(u: int, char: str) -> int:
        curr = u
        while curr > 0 and char not in children[curr]:
            curr = fail[curr]
        if char in children[curr]:
            return children[curr][char]
        return 0

    # Build transition matrix of size m x m
    # T[j][i] = number of transitions from valid_nodes[i] to valid_nodes[j]
    T = [[0] * m for _ in range(m)]
    alphabet_chars = list(alphabet)
    for i, u in enumerate(valid_nodes):
        for char in alphabet_chars:
            nxt = get_next(u, char)
            if not is_banned[nxt]:
                j = node_to_idx[nxt]
                T[j][i] += 1

    # Matrix multiplication and exponentiation
    def mat_mul(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k]:
                    for j in range(size):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A: list[list[int]], power: int) -> list[list[int]]:
        size = len(A)
        res = [[int(i == j) for j in range(size)] for i in range(size)]
        base = A
        while power > 0:
            if power & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            power >>= 1
        return res

    Tn = mat_pow(T, n)
    start_idx = node_to_idx[0]

    total = sum(Tn[i][start_idx] for i in range(m)) % MOD
    return total
